  float fog=1.-exp(-dist*.0016);gl_FragColor=vec4(mix(color,uFog,fog),1.);return;
 }
 if(uWater>5.5){vec2 uv=vLocal*2.;float edge=max(0.,1.-dot(uv,uv));gl_FragColor=vec4(.009,.045,.06,edge*edge*uColor.r);return;}
 if(uWater>4.5){
